// Phase 7 — v2 recent-blockhash self-check. PURE (no network, no React). Exercises the REAL v2
// code paths (buildCanonicalSolMessage, buildCanonicalSplMessage, signTransaction,
// verifySolPayment, extractSignedTxParts) against KNOWN-FIXED fixtures — the same SEED_HEX + golden
// SolReqV2 URIs the jest goldens use (app/__tests__/solana-tx.test.ts, solana-spl.test.ts). The
// jest goldens prove byte-exactness vs @solana/web3.js; this proves the wired code path actually
// executes on-device.
//
// App.tsx runs this on launch → logcat (`DPAY_SOL_SELFCHECK PASS`). It is the native-module /
// polyfill blind-spot gate: it proves SLIP-10 ed25519 derivation + bs58 + noble ed25519 + sha256 +
// the v2 message builders + the strict verifier all run on the real device (Hermes) — independent
// of the FFI and of any network. Deterministic: same seed → same payer → same signature.
//
// The SEED_HEX below is a TEST-ONLY fixture (committed in the jest goldens), not a real wallet
// seed — it derives a throwaway payer with no on-chain funds.

import {deriveSolanaKeypair} from './identity';
import {decodeSolReq} from './qr';
import {
  buildCanonicalSolMessage,
  signTransaction,
  verifySolPayment,
  extractSignedTxParts,
} from './tx';
import {buildCanonicalSplMessage} from './spl';
import {USDC_DECIMALS} from './tokens';

// Same fixtures as app/__tests__/solana-tx.test.ts + solana-spl.test.ts (generated by
// .dev/sol-poc/10-v2-canonical-golden.mjs). SLIP-10 m/44'/501'/0'/0' from SEED_HEX → the payer.
const SEED_HEX = '4f66b8c0a9b6e1f2d3a4c5b6e7f8a9b0c1d2e3f4a5b6c7d8e9f0a1b2c3d4e5f6';
const V2_PAYER_ADDRESS = '3jsvVphLjwR6wih9fQydrRNGieNjYzyMkyTxFueCssaK';
const V2_SOL_URI =
  'solreq:v2?';
const V2_USDC_URI =
  'solreq:v2?';

export type SolSelfCheckResult = {ok: true} | {ok: false; reason: string};

/** Run the v2 recent-blockhash self-check. PURE + sync + TOTAL — never throws (every failure maps
 *  to {ok:false,reason}). Returns {ok:true} iff: the derived payer matches the golden address, the
 *  SOL + USDC canonical messages build + sign + strict-verify round-trip, and the first signature
 *  extracts. Exercises ATA PDA derivation + TransferChecked for USDC. */
export function runSolSelfCheck(): SolSelfCheckResult {
  try {
    const kp = deriveSolanaKeypair(SEED_HEX);
    if (kp.address !== V2_PAYER_ADDRESS) return {ok: false, reason: `payer mismatch: ${kp.address}`};

    // SOL v2: build the canonical {Memo, System.transfer} message → sign → strict-verify → extract
    // the first signature. Proves sha256 memo + assembleMessage + ed25519 sign/verify on-device.
    const solReq = decodeSolReq(V2_SOL_URI);
    const solMsg = buildCanonicalSolMessage(kp.publicKey, solReq);
    const solTx = signTransaction(solMsg, kp.seed);
    const solRes = verifySolPayment(solMsg, {tx: solTx});
    if (!solRes.ok) return {ok: false, reason: `sol verify: ${solRes.reason}`};
    if (solRes.payer !== V2_PAYER_ADDRESS) return {ok: false, reason: `sol payer: ${solRes.payer}`};
    const solParts = extractSignedTxParts(solTx);
    if (!solParts || solParts.signature.length !== 64) return {ok: false, reason: 'sol sig extract'};

    // USDC v2: build the canonical {Memo, Token.transferChecked} message → sign → strict-verify.
    // Proves ATA PDA derivation + TransferChecked (mint + decimals commitment) on-device.
    const usdcReq = decodeSolReq(V2_USDC_URI);
    const usdcMsg = buildCanonicalSplMessage(kp.publicKey, usdcReq, USDC_DECIMALS);
    const usdcTx = signTransaction(usdcMsg, kp.seed);
    const usdcRes = verifySolPayment(usdcMsg, {tx: usdcTx});
    if (!usdcRes.ok) return {ok: false, reason: `usdc verify: ${usdcRes.reason}`};
    if (usdcRes.payer !== V2_PAYER_ADDRESS) return {ok: false, reason: `usdc payer: ${usdcRes.payer}`};

    return {ok: true};
  } catch (e) {
    return {ok: false, reason: e instanceof Error ? e.message : String(e)};
  }
}
